/* Reuse the frozen ID reader; add flow side just before its single output. */
#include "id_flow_abi.h"
static __attribute__((always_inline)) inline long id_flow_emit(
        void *, void *, jm_u64, void *, jm_u64);
#define message_id_state id_flow_state
/* Function-like expansion leaves the helper pointer declaration unchanged. */
#define emit(...) id_flow_emit(__VA_ARGS__)
#include "message_id.bpf.c"
#undef emit
#undef message_id_state

static __attribute__((always_inline)) inline long
id_flow_emit(void *context, void *map, jm_u64 flags, void *data, jm_u64 size)
{
    struct mi_ctx *ctx = context;
    struct jm_event *e = data;
    jm_u64 flow = ctx->arg[2];
    jm_u32 status = 0, side = 0;
    unsigned char type = 0;

    e->magic = IF_MAGIC;
    if ((e->flags & 3) || !flow) goto output;
    if (flow & 1) { status = IF_OUT_OF_SCOPE; goto output; }
    if (flow & 63) { status = IF_INVALID; goto output; }
    if (e->reads >= 80 || e->source_bytes >= 2048) {
        status = IF_BUDGET; goto output;
    }
    e->reads++; e->source_bytes++;
    if (read_mem(&type, 1, flow + 37)) {
        status = IF_READ_FAILED; goto output;
    }
    type &= 0xc0;
    if (type == 0x40) side = 1;
    else if (type == 0x80) side = 2;
    else { status = IF_INVALID; goto output; }
    status = IF_COMPLETE;
output:
    e->flags |= (side << IF_SIDE_SHIFT) | (status << IF_STATUS_SHIFT);
    return emit(context, map, flags, data, size);
}

substrate/surfaces/json_method_abi.h.text:
/* Fixed to the ca69b84f package's debug types; not a portable TMM ABI. */
#ifndef JSON_METHOD_ABI_H
#define JSON_METHOD_ABI_H
typedef unsigned int jm_u32;
typedef unsigned long long jm_u64;
enum jm_status {
    JM_COMPLETE = 1, JM_TRUNCATED, JM_READ_FAILED, JM_OUT_OF_SCOPE,
    JM_BUDGET, JM_GETTER_ERROR, JM_UNAVAILABLE
};
struct jm_event {
    jm_u32 magic, abi;
    jm_u64 instance, revision, run, monotonic_ns, sequence, output_failures;
    jm_u32 status, getter_result, original_length, copied_length;
    unsigned short flags, reads;
    jm_u32 source_bytes;
    unsigned char value[64];
};
/* Local read buffers. No complete object or address is exported. */
struct jm_value {
    jm_u32 type, pad;
    jm_u64 value[2];
    jm_u32 flags, token;
    jm_u64 cache, owner;
};
struct jm_member {
    jm_u64 key;
    jm_u32 len, pad, token, flags;
    jm_u64 value, next;
};
_Static_assert(sizeof(struct jm_event) == 144, "record ABI");
_Static_assert(sizeof(struct jm_value) == 48, "value layout");
_Static_assert(sizeof(struct jm_member) == 40, "member prefix layout");
#endif

